package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's household identifier before it is saved. The id is derived from the
 * owner's last name and address via {@link HouseholdKey#id(String, String)}, so every owner of
 * the same household — including those that opted in with {@code sharesHousehold=true} — receives
 * the same stable value. Runs after {@link BuildOwner} has produced the entity and before
 * {@link SaveOwner} persists it, mutating the built owner in place.
 */
public class AssignHouseholdId {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(HouseholdKey.id(owner.getLastName(), owner.getAddress()));
    }
}

===== EnsureUniqueHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request whose last name and address already belong to an existing owner,
 * so the pair maps to a 409 — unless the request opts in with {@code sharesHousehold=true},
 * declaring that the two owners share a household. Comparison is by {@link HouseholdKey}, so
 * case and whitespace differences do not hide a collision.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String key = HouseholdKey.of(request.getLastName(), request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (key.equals(HouseholdKey.of(existing.getLastName(), existing.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}

